import { action } from '@ember/object';
import { inject as service } from '@ember/service';
import { htmlSafe } from '@ember/template';
import Component from '@glimmer/component';
import { tracked } from '@glimmer/tracking';

// Written at build time (scripts/build-public.js): desks, features, the Hub's workspace id.
const HUB = {"hubId":"30b652d1-5f0e-4556-8a96-4863f009eb85","tourWorkspaceId":"59d602ed-70de-43b8-8690-6b7b274affc4","dataMapWorkspaceId":"adf7234f-7b80-48aa-88e9-7bc9ad56c1b9","desks":[{"key":"onboarding","name":"Onboarding desk","icon":"🛂","description":"Retail and business KYC: check the ID, the owners and the documents, then approve or ask for more.","workspaceId":"654efc2e-e63e-4bf5-89aa-a220fec2855b","queues":["kyc_retail","kyc_business","kyc_senior","kyc_parked","kyc_other"]},{"key":"alerts","name":"Alerts desk","icon":"🚨","description":"AML and fraud alerts raised by the rules: clear the noise, escalate the real ones.","workspaceId":"0de6234b-0b10-47fd-862b-a7f88f4c3845","queues":["alerts_aml","alerts_fraud"]},{"key":"investigations","name":"Investigations desk","icon":"🔎","description":"Open cases and screening hits: build the case file, ask for due diligence, draft the SAR.","workspaceId":"3b609bd4-8c1e-45b0-8ca5-04a2a18b9929","queues":["hits_open","inv_open"]},{"key":"mlro","name":"MLRO desk","icon":"⚖️","description":"The MLRO signs off: file the SAR, send it back to the analyst, or close without one.","workspaceId":"a20b591a-fc4d-4d01-8c85-559d571b1c29","queues":["mlro_signoff"]},{"key":"payments","name":"Payments desk","icon":"💶","description":"High-value transfers to validate, and the SEPA recalls other banks send us.","workspaceId":"35e0620c-79c2-45c3-8c6d-cac353ba9342","queues":["transfers_validate","recalls_in"]},{"key":"disputes","name":"Disputes desk","icon":"💳","description":"Card and SEPA disputes: route each request, file chargebacks, answer the merchant’s bank.","workspaceId":"9d9fa26f-31c8-4c99-874e-2154843f6ba5","queues":["disputes_new","cb_contested","cb_open"]},{"key":"overview","name":"Ops overview","icon":"📊","description":"Every queue of every team on one page: the manager’s view.","workspaceId":"6edb4352-9147-4d77-8cfc-4b31ec903f72","queues":["kyc_retail","kyc_business","kyc_senior","kyc_parked","kyc_other","alerts_aml","alerts_fraud","hits_open","inv_open","mlro_signoff","transfers_validate","recalls_in","disputes_new","cb_contested","cb_open"]}],"features":[{"name":"Collections & record pages","what":"Every table of your bank, browsable, with a page per customer that tells the story.","where":"Customers table: open a customer for its Customer 360.","workspaceId":"015fe3f1-901b-46de-8cab-33d6f79025bc","collection":null},{"name":"Segments","what":"Saved lists your whole team shares: “transfers to validate” is one click away.","where":"Alerts table: AML alerts to review, Fraud and takeover alerts.","workspaceId":"3822638d-f3ec-41f3-8bd4-136d7e01dc26","collection":null},{"name":"Inboxes & queues","what":"Each analyst gets the next task, in the right order, and nobody works the same case twice.","where":"Onboarding desk: Retail onboarding, Business onboarding.","workspaceId":"ae9d5300-7124-41c7-8557-49758f9cda30","collection":null},{"name":"Workflows","what":"Your procedure, step by step on screen: the analyst follows it, and the hard cases go up.","where":"Alerts desk: Fraud and takeover alert. Payments desk: High-value transfer validation.","workspaceId":"e2607278-3d14-48e7-880c-36610417b4a2","collection":null},{"name":"Smart Actions","what":"Your business operations as buttons: a form, your code runs, a card shows what it did.","where":"MLRO desk: File SAR. Disputes desk: Route dispute, File with network.","workspaceId":"8da7be9d-4b5c-4916-8e38-36c0f1a6004d","collection":null},{"name":"Charts & analytics","what":"Live counters and graphs on your data, where the team works, with no BI project.","where":"Ops overview: a live counter per queue, across the teams.","workspaceId":"d714bf27-ffca-429d-8b7d-86f7c56b8441","collection":null},{"name":"Workspaces & the layout editor","what":"A page per team: its queue, the case, and the buttons to act, without a line of code.","where":"Every desk. The Hub and this page are workspaces too.","workspaceId":"b4b80f61-2e70-4e10-8cb6-33e3926a5839","collection":null},{"name":"Custom components","what":"When the built-in blocks are not enough, drop your own HTML, code and style into a page.","where":"This Hub: the cards, the live counts and the tour button.","workspaceId":"41af05cf-b309-4601-8c7d-6912c5719da2","collection":null},{"name":"Roles, teams & permissions","what":"Analysts see what they need and do what they may; the MLRO signs, the rest cannot.","where":"This demo runs as the Operations team. Project settings, Roles.","workspaceId":"df6f1e14-8e6e-441f-8a36-ac38932019d6","collection":null},{"name":"The agent & data privacy","what":"Your data never leaves your infrastructure: Forest sees the shape of your tables, not the rows.","where":"This demo’s agent runs on this Mac, on port 3310.","workspaceId":"cf02cd81-1f7f-4476-8057-45e19220ba66","collection":null},{"name":"AI in Forest","what":"AI that decides inside your procedure, explains why, and stays inside your permissions.","where":"Alerts desk: the Fraud and takeover alert workflow decides with AI.","workspaceId":"525f3c1f-cb4d-44f1-8242-5614d9fdbce6","collection":null},{"name":"Activity log & audit","what":"Who did what, on which record, and when: every click an auditor will ask about.","where":"Any record: its Activity tab.","workspaceId":"2ce0420b-42fd-4e69-81b6-39b1788c407c","collection":null}]}
const MODE = "back"

const UUID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;
// Forest's grid cell, in px (WORKSPACE_GRID_CELL_WIDTH and _HEIGHT).
const CELL = 20;
const BACK_LABEL = '← Hub';

/** As select-first's: one line, at most 40% of the box's height, the whole text in its width. */
function fittedFont(component, text, { min = 11, max = 36 } = {}) {
  const box = component?.displaySettings;
  if (!box?.width || !box?.height) return null;
  const byHeight = box.height * CELL * 0.4;
  const byWidth = (box.width * CELL - 44) / (0.6 * Math.max(String(text).length, 1));

  return Math.round(Math.max(min, Math.min(max, byHeight, byWidth)));
}

export default class extends Component {
  @service lianaServerFetch;

  @service router;

  @tracked counts = null;

  @tracked countsStatus = 'Counting…';

  features = HUB.features.map(f => ({ ...f, clickable: Boolean(f.workspaceId || f.collection) }));

  dataMapWorkspaceId = HUB.dataMapWorkspaceId || null;

  constructor(...args) {
    super(...args);
    if (MODE === 'hub') this.loadCounts();
  }

  async loadCounts() {
    try {
      const response = await this.lianaServerFetch.fetch('/forest/_charts/hub_counts', {});
      if (!response.ok) throw new Error(`hub_counts: ${response.status}`);
      this.counts = await response.json();
    } catch (error) {
      this.countsStatus = 'Counts unavailable';
    }
  }

  /** The "← Hub" button's text size, from its box. */
  get backStyle() {
    const size = fittedFont(this.args.component, BACK_LABEL);

    return size ? htmlSafe(`font-size:${size}px`) : null;
  }

  /** hub_counts answers per queue: a desk adds up its own queues (HUB.desks[].queues). */
  static deskCounts(desk, byQueue) {
    if (!byQueue) return null;
    const mine = (desk.queues || []).map(key => [key, byQueue[key]]);
    if (mine.some(([, q]) => !q)) return null;
    const total = field => mine.reduce((sum, [, q]) => sum + q[field], 0);

    return {
      waiting: total('waiting'),
      overdue: total('overdue'),
      hasDeadline: mine.some(([, q]) => q.hasDeadline),
      queues: Object.fromEntries(mine.map(([key, q]) => [key, q.waiting])),
    };
  }

  get desks() {
    const byQueue = this.counts?.queues;

    return HUB.desks.map(desk => {
      const c = this.constructor.deskCounts(desk, byQueue);
      if (!c) return { ...desk, counts: null };
      let second = null;
      if (c.hasDeadline) second = c.overdue ? `${c.overdue} overdue` : 'none overdue';

      return { ...desk, counts: { waiting: c.waiting, second } };
    });
  }

  /** The current url with the workspace id swapped: no need to know Forest's url scheme. */
  static workspacePath(workspaceId) {
    const path = window.location.pathname;
    const ids = path.match(UUID) || [];
    const current = HUB.hubId && path.includes(HUB.hubId) ? HUB.hubId : ids[ids.length - 1];
    if (!current) return null;
    const at = path.lastIndexOf(current);

    return `${path.slice(0, at)}${workspaceId}`;
  }

  /** A table's list, assuming /<project>/<environment>/<team>/data/<table>/index. */
  static tablePath(collection) {
    const [project, environment, team] = window.location.pathname.split('/').filter(Boolean);

    return `/${project}/${environment}/${team}/data/${collection}/index`;
  }

  /** Inside the app when the router knows the url, else a full page load. */
  go(path) {
    if (!path) return;

    try {
      const transition = this.router.transitionTo(path);
      transition?.catch?.(error => {
        if (error?.name !== 'TransitionAborted') window.location.assign(path);
      });
    } catch (error) {
      window.location.assign(path);
    }
  }

  @action
  openWorkspace(workspaceId) {
    this.go(this.constructor.workspacePath(workspaceId));
  }

  @action
  openFeature(feature) {
    if (feature.workspaceId) this.openWorkspace(feature.workspaceId);
    else if (feature.collection) this.go(this.constructor.tablePath(feature.collection));
  }

  @action
  openHub() {
    this.openWorkspace(HUB.hubId);
  }

  /** The tour: the demo path's first desk (the Simplified onboarding desk). */
  @action
  openTour() {
    if (HUB.tourWorkspaceId) this.openWorkspace(HUB.tourWorkspaceId);
  }

  /** The data model workspace (the demo layout's): every table, by domain. */
  @action
  openDataMap() {
    this.openWorkspace(HUB.dataMapWorkspaceId);
  }
}
